import json
def transform(g):
    H,W=len(g),len(g[0])
    colors=set(v for row in g for v in row if v)
    masks=[]
    for col in colors:
        cells={(r,c) for r in range(H) for c in range(W) if g[r][c]==col}
        seen=set()
        for cell in cells:
            if cell in seen: continue
            stack=[cell]; seen.add(cell); cs=[]
            while stack:
                a,b=stack.pop(); cs.append((a,b))
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        if dr or dc:
                            x,y=a+dr,b+dc
                            if (x,y) in cells and (x,y) not in seen:
                                seen.add((x,y)); stack.append((x,y))
            rows=sorted(set(r for r,c in cs)); cols_=sorted(set(c for r,c in cs))
            rect=len(cs)==(rows[-1]-rows[0]+1)*(cols_[-1]-cols_[0]+1)
            if not rect and len(cs)>3:
                r0=rows[0]; h=rows[-1]-rows[0]+1
                masks.append((col,{(r-r0,c) for r,c in cs},r0,h))
    # bar: rectangular component with multiple colors
    seen=set()
    bar=None
    allnz={(r,c) for r in range(H) for c in range(W) if g[r][c]}
    for cell in allnz:
        if cell in seen: continue
        stack=[cell]; seen.add(cell); cs=[]
        while stack:
            a,b=stack.pop(); cs.append((a,b))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    if dr or dc:
                        x,y=a+dr,b+dc
                        if (x,y) in allnz and (x,y) not in seen:
                            seen.add((x,y)); stack.append((x,y))
        rows=sorted(set(r for r,c in cs)); cols_=sorted(set(c for r,c in cs))
        if len(cs)==(rows[-1]-rows[0]+1)*(cols_[-1]-cols_[0]+1) and len(cs)>1 and len(set(g[r][c] for r,c in cs))>1:
            bar=cs
    bcols=sorted(set(c for r,c in bar))
    bar_colors=[]
    for c in bcols:
        for r,cc in bar:
            if cc==c: v=g[r][c]; break
        if v not in bar_colors: bar_colors.append(v)
    col,mask,r0,h=masks[0]
    idx=bar_colors.index(col)
    top=r0-idx*h
    out=[[0]*W for _ in range(H)]
    for i,c2 in enumerate(bar_colors):
        for dr,dc in mask: out[top+i*h+dr][dc]=c2
    return out

